/// load_image Loads an image from the Cartridge's assets, once per path, and returns its handle. The page decodes it in the background and the guest gets an image_loaded event (or an error event). Paths must be under assets/.
/// It takes input of types::CanvasLoadInput ()
/// And it returns an output types::CanvasLoadOutput ()
#[allow(unused)]
pub(crate) fn load_image(
    input: types::CanvasLoadInput,
) -> std::result::Result<types::CanvasLoadOutput, extism_pdk::Error> {
    let res = unsafe { raw_imports::load_image(extism_pdk::Json(input))? };

    let extism_pdk::Json(res) = res;

    Ok(res)
}

/// load_sound Loads a sound from the Cartridge's assets, once per path, and returns its handle. The page decodes it in the background and the guest gets a sound_loaded event (or an error event).
/// It takes input of types::CanvasLoadInput ()
/// And it returns an output types::CanvasLoadOutput ()
#[allow(unused)]
pub(crate) fn load_sound(
    input: types::CanvasLoadInput,
) -> std::result::Result<types::CanvasLoadOutput, extism_pdk::Error> {
    let res = unsafe { raw_imports::load_sound(extism_pdk::Json(input))? };

    let extism_pdk::Json(res) = res;

    Ok(res)
}

/// measure_text Measures text in the font that a font declaration of the same family, size and weight would select. Results are in pixels.
/// It takes input of types::MeasureTextInput ()
/// And it returns an output types::MeasureTextOutput ()
#[allow(unused)]
pub(crate) fn measure_text(
    input: types::MeasureTextInput,
) -> std::result::Result<types::MeasureTextOutput, extism_pdk::Error> {
    let res = unsafe { raw_imports::measure_text(extism_pdk::Json(input))? };

    let extism_pdk::Json(res) = res;

    Ok(res)
}

/// play_sound Plays a loaded sound and returns its playback id. At most 8 sounds play at once, and calls made while the canvas is muted or off-screen return an id and play nothing.
/// It takes input of types::CanvasPlaySoundInput ()
/// And it returns an output types::CanvasPlaySoundOutput ()
#[allow(unused)]
pub(crate) fn play_sound(
    input: types::CanvasPlaySoundInput,
) -> std::result::Result<types::CanvasPlaySoundOutput, extism_pdk::Error> {
    let res = unsafe { raw_imports::play_sound(extism_pdk::Json(input))? };

    let extism_pdk::Json(res) = res;

    Ok(res)
}

/// request_frame Asks for one more frame. A guest that animates calls it again each frame. Takes no input.
/// And it returns an output types::CanvasHostReply ()
#[allow(unused)]
pub(crate) fn request_frame() -> std::result::Result<types::CanvasHostReply, extism_pdk::Error> {
    let res = unsafe { raw_imports::request_frame()? };

    let extism_pdk::Json(res) = res;

    Ok(res)
}

/// send Sends one message to the Server Guest's on_canvas_message. The answer comes later as a reply or error event with the same seq. At most 4 in flight, and at most 4 KiB of JSON per message.
/// It takes input of types::CanvasSendInput ()
/// And it returns an output types::CanvasHostReply ()
#[allow(unused)]
pub(crate) fn send(
    input: types::CanvasSendInput,
) -> std::result::Result<types::CanvasHostReply, extism_pdk::Error> {
    let res = unsafe { raw_imports::send(extism_pdk::Json(input))? };

    let extism_pdk::Json(res) = res;

    Ok(res)
}

/// set_fps Sets the requested frame rate at any time. Clamped to 1 to 60, and reduced motion caps it at 15.
/// It takes input of types::SetFpsInput ()
/// And it returns an output types::CanvasHostReply ()
#[allow(unused)]
pub(crate) fn set_fps(
    input: types::SetFpsInput,
) -> std::result::Result<types::CanvasHostReply, extism_pdk::Error> {
    let res = unsafe { raw_imports::set_fps(extism_pdk::Json(input))? };

    let extism_pdk::Json(res) = res;

    Ok(res)
}

/// stop_sound Stops a playing sound by its playback id. An id that is not playing is a no-op.
/// It takes input of types::CanvasStopSoundInput ()
/// And it returns an output types::CanvasHostReply ()
